shell_commands.command:
cd /testbed && patch -p1 <<'PATCH'
--- a/tests/by-util/test_cp.rs
+++ b/tests/by-util/test_cp.rs
@@ -95,6 +95,17 @@
 }

 #[test]
+fn test_cp_zsh_completion() {
+    let ts = TestScenario::new(util_name!());
+    ts.ccmd("completion")
+        .args(&["cp", "zsh"])
+        .succeeds()
+        .no_stderr()
+        .stdout_contains_line("'*::paths:_files'");
+}
+
+#[test]
 fn test_cp_existing_target() {
     let (at, mut ucmd) = at_and_ucmd!();
     ucmd.arg(TEST_HELLO_WORLD_SOURCE)
PATCH
cargo test -- test_cp_zsh_completion

cd /testbed && patch -p1 <<'PATCH' && cargo test -- test_cp_zsh_completion > target/cp-completion-regression.log 2>&1
--- a/tests/by-util/test_cp.rs
+++ b/tests/by-util/test_cp.rs
@@ -95,6 +95,16 @@
 }

 #[test]
+fn test_cp_zsh_completion() {
+    let ts = TestScenario::new(util_name!());
+    ts.ccmd("completion")
+        .args(&["cp", "zsh"])
+        .succeeds()
+        .no_stderr()
+        .stdout_contains_line("'*::paths:_files'");
+}
+
+#[test]
 fn test_cp_existing_target() {
     let (at, mut ucmd) = at_and_ucmd!();
     ucmd.arg(TEST_HELLO_WORLD_SOURCE)
PATCH
status=$?; tail -85 target/cp-completion-regression.log; exit "$status"

